/* Five more slot heaps that only the Splice VM uses. They are template statics too: StaticInit_spliceutils initializes
 * them, sentry-guarded, after the six engine pools (CONFIRMED by match; HYPOTHESIS: the template shape and name).
 * Their objects are 0x18 apart (0x452188..0x4521E8), i.e. a bare SLOTHEAP. */
template <int CB, int C>
struct CSpliceHeap
{
      SLOTHEAP slotheap;
      CSpliceHeap() { func_0011CCA8(&slotheap, CB, C, 16); }
      static CSpliceHeap s_heap;
};
template <int CB, int C> CSpliceHeap<CB, C> CSpliceHeap<CB, C>::s_heap;
template CSpliceHeap<0x20, 0x100> CSpliceHeap<0x20, 0x100>::s_heap;
